-- ADCT, comentários didáticos, lote 3 (arts. 22 a 31), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Opção dos defensores públicos pela carreira$c$, aplicacao_pratica = $a$Assegura aos defensores públicos investidos na função até a data de instalação da Assembleia Nacional Constituinte o direito de opção pela carreira, observadas as garantias e vedações do art. 134, parágrafo único, da Constituição.$a$ where codigo='adct' and numero=22 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Censores federais$c$, aplicacao_pratica = $a$Determina que, até a regulamentação do art. 21, XVI, da Constituição, os atuais ocupantes do cargo de censor federal continuem exercendo funções compatíveis no Departamento de Polícia Federal, observadas as disposições constitucionais. O parágrafo único atribui à lei referida dispor sobre o aproveitamento dos Censores Federais.$a$ where codigo='adct' and numero=23 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Compatibilização dos quadros de pessoal$c$, aplicacao_pratica = $a$Determinou que União, Estados, Distrito Federal e Municípios editassem leis com critérios para compatibilizar seus quadros de pessoal ao art. 39 da Constituição e à reforma administrativa dela decorrente, em dezoito meses contados da promulgação. Norma transitória de aplicação já exaurida quanto ao prazo.$a$ where codigo='adct' and numero=24 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Revogação de delegações ao Executivo e decretos-lei$c$, aplicacao_pratica = $a$Revogou, a partir de cento e oitenta dias da promulgação, prazo prorrogável por lei, os dispositivos legais que atribuíssem ou delegassem a órgão do Poder Executivo competência assinalada pela Constituição ao Congresso Nacional, especialmente quanto à ação normativa (I) e à alocação ou transferência de recursos (II). O § 1º regulou os decretos-lei em tramitação, apreciados em até cento e oitenta dias se editados até 2 de setembro de 1988 e considerados rejeitados se não apreciados, com validade dos atos praticados (I a III), e o § 2º converteu em medidas provisórias os decretos-lei editados entre 3 de setembro de 1988 e a promulgação, aplicando-se o art. 62, parágrafo único.$a$ where codigo='adct' and numero=25 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Exame do endividamento externo$c$, aplicacao_pratica = $a$Determinou que o Congresso Nacional promovesse, em um ano da promulgação, por Comissão mista, exame analítico e pericial dos atos e fatos geradores do endividamento externo brasileiro. O § 1º deu à Comissão a força legal de comissão parlamentar de inquérito para requisição e convocação, com o auxílio do Tribunal de Contas da União, e o § 2º previu, apurada irregularidade, a proposta ao Executivo de declaração de nulidade do ato e o encaminhamento ao Ministério Público Federal, que formalizaria a ação cabível em sessenta dias. Norma transitória de aplicação já exaurida quanto ao prazo.$a$ where codigo='adct' and numero=26 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Instalação do Superior Tribunal de Justiça e dos TRFs$c$, aplicacao_pratica = $a$Previu a instalação do Superior Tribunal de Justiça sob a Presidência do Supremo Tribunal Federal. O § 1º manteve as competências do ordenamento anterior com o Supremo até a instalação, o § 2º definiu a composição inicial pelo aproveitamento dos Ministros do Tribunal Federal de Recursos (I) e pela nomeação dos necessários para completar o número (II), os §§ 3º e 4º trataram da classe de origem e da aposentadoria desses Ministros, o § 5º da lista tríplice, o § 6º da criação de cinco Tribunais Regionais Federais em seis meses, o § 7º da competência transitória do Tribunal Federal de Recursos, o § 8º da vedação de provimento de suas vagas, o § 9º da promoção de juiz com menos de cinco anos de exercício na falta de candidato, o § 10 da competência para as ações e rescisórias anteriores à promulgação e o § 11 da criação de outros Tribunais Regionais Federais, com as sedes e jurisdições que indica.$a$ where codigo='adct' and numero=27 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Juízes federais do regime anterior$c$, aplicacao_pratica = $a$Investiu na titularidade de varas, na Seção Judiciária para a qual tenham sido nomeados ou designados, os juízes federais do art. 123, § 2º, da Constituição de 1967, com a redação da Emenda Constitucional nº 7/1977, procedendo-se ao desdobramento das varas existentes na falta de vagas. O parágrafo único computa o tempo de serviço desses juízes, para promoção por antiguidade, a partir do dia da posse.$a$ where codigo='adct' and numero=28 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Ministério Público e Advocacia-Geral da União na transição$c$, aplicacao_pratica = $a$Manteve, enquanto não aprovadas as leis complementares do Ministério Público e da Advocacia-Geral da União, as atividades do Ministério Público Federal, da Procuradoria-Geral da Fazenda Nacional, das Consultorias Jurídicas dos Ministérios, das Procuradorias e Departamentos Jurídicos de autarquias federais com representação própria e das Procuradorias das Universidades fundacionais públicas. O § 1º fixou em cento e vinte dias o envio do projeto de lei complementar da Advocacia-Geral da União, o § 2º facultou aos Procuradores da República opção irretratável entre as carreiras, o § 3º permitiu ao membro do Ministério Público admitido antes da promulgação optar pelo regime anterior quanto a garantias e vantagens, o § 4º integrou à carreira os do quadro suplementar dos Ministérios Públicos do Trabalho e Militar com estabilidade e o § 5º manteve a representação judicial da União em causas fiscais pela Procuradoria-Geral da Fazenda Nacional até as leis complementares.$a$ where codigo='adct' and numero=29 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Justiça de paz na transição$c$, aplicacao_pratica = $a$Determina que a legislação que criar a justiça de paz mantenha os atuais juízes de paz até a posse dos novos titulares, assegurando-lhes os direitos e atribuições destes, e designe o dia da eleição prevista no art. 98, II, da Constituição.$a$ where codigo='adct' and numero=30 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Estatização das serventias do foro judicial$c$, aplicacao_pratica = $a$Determina a estatização das serventias do foro judicial, assim definidas em lei, respeitados os direitos dos atuais titulares.$a$ where codigo='adct' and numero=31 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
